def serialize(obj):
    """ Serialize Python object to PDF syntax byte string """
    if isinstance(obj, dict):
        items = []
        for k, v in obj.items():
            items.append(serialize(k))
            items.append(serialize(v))
        return b'<< ' + b' '.join(items) + b' >>'
    elif isinstance(obj, list):
        items = [serialize(item) for item in obj]
        return b'[ ' + b' '.join(items) + b' ]'
    elif isinstance(obj, bool):
        return b'true' if obj else b'false'
    elif isinstance(obj, int) or isinstance(obj, float):
        return str(obj).encode('ascii')
    elif isinstance(obj, str):
        # Handle string serialization (for names and literals)
        if obj.startswith('/'):
            return obj.encode('ascii')
        else:
            # For literal strings, we need to encode them properly
            return b'(' + obj.encode('utf-8') + b')'
    elif isinstance(obj, bytes):
        return obj
    else:
        # Default to string representation
        return str(obj).encode('ascii')


def next_token(text, i=0):
    """ syntax Find next token in raw string starting at some index
    """
    search = "TBD"
    nested = 1
    h = i
    while i < len(text):
        single = text[i:i+1]
        double = text[i:i+2]
        if search == "TBD":
            if double == b'<<':
                search = "DICT"
            elif single == b'[':
                search = "ARRAY"
            elif single == b'/':
                search = "NAME"
            elif text[i:i+6] == b"stream":
                search = "STREAM"
                offset = 7 if text[i+6:i+7] == b'\n' else 8 # else is b'\r\n'
                i += offset
            elif single in b"+-.0123456789":
                search = "VALUE"
            elif single in b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
                search = "KEYWORD"
            elif single in b"(<":
                search = "TEXT"
            elif single == b't':
                # Check for true/false keywords
                if text[i:i+4] == b'true':
                    return (i, i+4, 'TRUE')
                elif text[i:i+5] == b'false':
                    return (i, i+5, 'FALSE')
            elif single == b'%':
                # Skip comment - find the actual start of the comment (skip leading whitespace)
                # Set h to the position of the % character
                h = i
                while i < len(text) and text[i:i+1] not in b'\r\n':
                    i += 1
                while i < len(text) and text[i:i+1] in b'\r\n':
                    i += 1
                return (h, i, 'COMMENT')
            h = i
        elif search == "DICT":
            if double == b'<<':
                nested += 1
                i += 1
            elif double == b'>>':
                nested -= 1
                i += 1
            if nested == 0:
                return (h, i + 1, 'DICT')
        elif search == "NAME":
            if single in b' \n\r[]/<>(' or i >= len(text):
                return (h, i, 'NAME')
            i += 1
            continue
        elif search == "TEXT":
            if double == b'\\(' or double == b'\\)' or double == b'\\<' or double == b'\\>':
                i += 1
            elif single == b'(':
                # Handle opening parenthesis in literal strings
                paren_count = 1
                i += 1
                while i < len(text) and paren_count > 0:
                    if text[i:i+1] == b'(':
                        paren_count += 1
                    elif text[i:i+1] == b')':
                        paren_count -= 1
                    i += 1
                return (h, i, 'STRING')
            elif single == b'<':
                # Handle hexadecimal strings
                i += 1
                while i < len(text) and text[i:i+1] not in b'>':
                    i += 1
                if i < len(text) and text[i:i+1] == b'>':
                    i += 1
                return (h, i, 'STRING')
            elif single in b')>':
                return (h, i + 1, 'STRING')
            i += 1
            continue
        elif search == "KEYWORD":
            if single in b' \n\r>/]' or i >= len(text) or i == len(text) - 1:
                # Check if it's a special keyword
                keyword = text[h:i]
                if keyword == b'true':
                    return (h, i, 'TRUE')
                elif keyword == b'false':
                    return (h, i, 'FALSE')
                return (h, i, 'KEYWORD')
        elif search == "VALUE":
            # Check if we've reached the end of the string
            if i >= len(text):
                return (h, i, None)
            # If we're at the last character, we need to check if it's a valid terminator
            if i == len(text) - 1:
                # We're at the last character of the string, and it's a value character
                # This means the token is incomplete
                return (h, i + 1, None)
            if single in b' \n\r>/]':
                # Determine if it's integer or real
                if b'.' in text[h:i] or b'e' in text[h:i].lower():
                    return (h, i, 'REAL')
                else:
                    return (h, i, 'INTEGER')
            i += 1
            continue
        elif search == "STREAM":
            if text[i:i+11] == b'\r\nendstream' or text[i:i+10] == b'\nendstream':
                return (h, i, 'STREAM')
        elif search == "ARRAY":
            if single == b'[':
                nested += 1
            elif single == b']':
                nested -= 1
            if nested == 0:
                return (h, i + 1, 'ARRAY')
        i += 1

    # Handle incomplete tokens at end of string
    # For incomplete tokens, we return (start_index, end_index, None)
    # Check if we have a partial token that would be incomplete
    if search == "NAME":
        return (h, i, None)
    elif search == "VALUE":
        # Return incomplete VALUE token
        return (h, i, None)
    elif search == "TEXT":
        # Incomplete TEXT token
        return (h, i, None)
    elif search == "DICT":
        # Incomplete DICT token
        return (h, i, None)
    elif search == "ARRAY":
        # Incomplete ARRAY token
        return (h, i, None)

    # For all other cases, return None for the token type (incomplete)
    return (h, i, None)


