    i = 0
    while i < size:
        # Check if we have a potential reference: number 0 R
        # Since tokens are raw bytes, we need to check for bytes objects
        if (i < size - 2 and 
            isinstance(tokens[i], (bytes, str)) and 
            tokens[i+1] == b'0' and 
            tokens[i+2] == b'R'):
            # Create a complex number representation for reference (as done in original)
            # This follows the convention that 6 0 R becomes 6j
            try:
                ref_num = int(tokens[i])
                new_list.append(complex(0, ref_num))
                i += 3
            except (ValueError, TypeError):
                # If conversion fails, treat as regular token
                new_list.append(tokens[i])
                i += 1
        else:
            new_list.append(tokens[i])
            i += 1
    return new_list


def decode_predictor(bdata, predictor, columns):
    size = len(bdata)
    res = b''
    columns += 1
    prev_row = [0] * columns
    i = 0
    while i < size:
        row = list(bdata[i:i+columns])
        decoded_row = [(val + prev_row[index]) & 0xff for (index, val) in enumerate(row)]
        prev_row = decoded_row
        res += bytes(decoded_row[1:])
        i += columns
    return res


def decode_stream(stream, stream_def):
    res = stream
    if b'/Filter' in stream_def and stream_def[b'/Filter'] == b'/FlateDecode':
        res = zlib.decompress(stream) #+ b'\r')
    if b'/DecodeParms' in stream_def and b'/Predictor' in stream_def[b'/DecodeParms']:
        predictor = int(stream_def[b'/DecodeParms'][b'/Predictor'])
        columns = int(stream_def[b'/DecodeParms'][b'/Columns'])
        res = decode_predictor(res, predictor, columns)
    return res


def parse_obj(text, start=0):
    """ syntax
    """
    # Skip leading whitespace and comments
    i = start
    while i < len(text):
        # Skip whitespace
        while i < len(text) and text[i:i+1] in b' \n\r\t':
            i += 1

        # Skip comments
        if i < len(text) and text[i:i+1] == b'%':
            while i < len(text) and text[i:i+1] not in b'\r\n':
                i += 1
            while i < len(text) and text[i:i+1] in b'\r\n':
                i += 1
            continue

        break

    if i >= len(text):
        return None

    h1, j1, t1 = next_token(text, i)
    if t1 == 'DICT':
        res = {}
        i = h1 + 2  # Skip the << 
        while i < j1 - 2:  # Skip the >>
            # Skip whitespace and comments before key
            while i < j1 - 2:
                # Skip whitespace
                while i < j1 - 2 and text[i:i+1] in b' \n\r\t':
                    i += 1

                # Skip comments
                if i < j1 - 2 and text[i:i+1] == b'%':
                    while i < j1 - 2 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 2 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 2:
                break

            # Parse key
            h_key, i, t_key = next_token(text, i)
            if t_key == 'NAME':
                key = text[h_key:i].decode('ascii')
            elif t_key == 'KEYWORD':
                key = text[h_key:i].decode('ascii')
            else:
                # Skip invalid keys
                continue

            # Skip whitespace and comments after key
            while i < j1 - 2:
                # Skip whitespace
                while i < j1 - 2 and text[i:i+1] in b' \n\r\t':
                    i += 1

                # Skip comments
                if i < j1 - 2 and text[i:i+1] == b'%':
                    while i < j1 - 2 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 2 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 2:
                break

            # Parse value
            h_val, i, t_val = next_token(text, i)
            if t_val:
                if t_val == 'DICT':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'ARRAY':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'TRUE':
                    obj = True
                elif t_val == 'FALSE':
                    obj = False
                elif t_val == 'NAME':
                    obj = text[h_val:i].decode('ascii')
                elif t_val == 'INTEGER' or t_val == 'REAL':
                    try:
                        obj = float(text[h_val:i]) if b'.' in text[h_val:i] or b'e' in text[h_val:i].lower() else int(text[h_val:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h_val:i]
                elif t_val == 'STRING':
                    obj = text[h_val:i]
                else:
                    obj = text[h_val:i]
                res[key] = obj
        return res

    elif t1 == 'ARRAY':
        res = []
        i = h1 + 1  # Skip the [
        while i < j1 - 1:  # Skip the ]
            # Skip whitespace and comments
            while i < j1 - 1:
                # Skip whitespace
                while i < j1 - 1 and text[i:i+1] in b' \n\r\t':
                    i += 1

                # Skip comments
                if i < j1 - 1 and text[i:i+1] == b'%':
                    while i < j1 - 1 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 1 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 1:
                break

            h, i, ttt = next_token(text, i)
            if ttt:
                if ttt == 'DICT':
                    obj = parse_obj(text[h:i])
                elif ttt == 'ARRAY':
                    obj = parse_obj(text[h:i])
                elif ttt == 'TRUE':
                    obj = True
                elif ttt == 'FALSE':
                    obj = False
                elif ttt == 'NAME':
                    obj = text[h:i].decode('ascii')
                elif ttt == 'INTEGER' or ttt == 'REAL':
                    try:
                        obj = float(text[h:i]) if b'.' in text[h:i] or b'e' in text[h:i].lower() else int(text[h:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h:i]
                elif ttt == 'STRING':
                    obj = text[h:i]
                else:
                    obj = text[h:i]
                res.append(obj)
        # Process references in array
        res = replace_ref(res)
        return res
    elif t1 == 'TRUE':
        return True
    elif t1 == 'FALSE':
        return False
    else:
        return None


def beginning_next_non_empty_line(bdata, i):
    """ doc
    """
    EOL = b'\r\n'
    while i < len(bdata) and bdata[i:i+1] not in EOL:
        i += 1
    while i < len(bdata) and bdata[i:i+1] in EOL:
        i += 1
    return i

"""Module for text decoding functions"""

import re
